=Output ONLY valid JSON. No conversational text, no explanations, no markdown blocks. 

Generate a welcome email for the student based on the following details:
- Name: {{ $json.Name }}
- Email: {{ $json.Email }}
- Course: {{ $json.Course }}
- DOJ: {{ $json.DOJ }}
- Place: {{ $json.Place }}

RULES:
1. If the email field above is missing, blank, or empty, you MUST set the "to" field value to "aurelity9@gmail.com". Otherwise, use the student's actual email address.
2. Output a clean JSON object with "to", "subject", and "body" fields.

Use this exact JSON structure:
{
  "to": "student's email here (or aureliyt9@gmail.com if empty)",
  "subject": "Welcome to the {{ $json.Course }} Course!",
  "body": "Dear {{ $json.Name }},\n\nWelcome aboard! Your enrollment in the {{ $json.Course }} course starting on {{ $json.DOJ }} is confirmed.\n\nWe are thrilled to have you in {{ $json.Place }}. If you have any questions, feel free to reach out.\n\nBest regards,\nThe Admissions Team"
}

parameters.jsCode:
// 1. Loop through ALL items coming into the Code node
const items = $input.all();
let allRecords = [];

// Define your default admin email here
const adminEmail = "aureliyt9@gmail.com";

for (const item of items) {
  const jsonItem = item.json || item;

  // Extract raw text from the "Message a model" node structure
  let raw =
    jsonItem.output?.[0]?.content?.[0]?.text ||   
    jsonItem.text ||                               
    jsonItem.message?.content ||                   
    '';

  if (typeof raw !== 'string') {
    raw = JSON.stringify(raw);
  }

  // 2. Clean conversational text and markdown code blocks
  let cleaned = raw.replace(/```json/gi, "").replace(/```/g, "").trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
  if (jsonMatch) {
    cleaned = jsonMatch[0];
  }

  let parsedData;
  try {
    parsedData = JSON.parse(cleaned);
  } catch (e) {
    // Fallback if JSON parsing fails: route to admin email
    allRecords.push({
      to: adminEmail,
      subject: "Enrollment Notification / Parse Error",
      body: cleaned || "No text received from the model"
    });
    continue;
  }

  // 3. Normalize records into an array
  let records = [];
  if (Array.isArray(parsedData)) {
    records = parsedData;
  } else if (parsedData.emails && Array.isArray(parsedData.emails)) {
    records = parsedData.emails;
  } else if (parsedData.students && Array.isArray(parsedData.students)) {
    records = parsedData.students;
  } else {
    records = [parsedData];
  }

  // 4. Extract fields, check for empty emails, and assign admin fallback
  for (const entry of records) {
    const normalized = {};
    for (let key in entry) {
      if (entry.hasOwnProperty(key)) {
        normalized[key.toLowerCase()] = entry[key];
      }
    }

    let to = normalized['to'] || normalized['email'] || normalized['mail'] || '';
    let subject = normalized['subject'] || normalized['title'] || 'Welcome to Your Course!';
    let body = normalized['body'] || normalized['message'] || '';

    if (!body && typeof entry === 'object') {
      const parts = [normalized['greeting'], normalized['body'], normalized['encouragement'], normalized['closing'], normalized['signature']].filter(Boolean);
      if (parts.length > 0) {
        body = parts.join('\n\n');
      }
    }

    // --- ADMIN EMAIL FALLBACK RULE ---
    // If 'to' is missing, blank, or contains a dummy placeholder, redirect to admin email
    if (!to || String(to).trim() === '' || String(to).includes('student@example.com') || String(to).includes('undefined')) {
      to = adminEmail;
    }

    allRecords.push({
      to: String(to).trim(),
      subject: String(subject).trim(),
      body: String(body).trim()
    });
  }
}

// 5. Return all items for batch email processing
return allRecords.map(record => ({ json: record }));
